            '0'..='9' => self.scan_number(src),
            '.' => {
                // Lookahead: `.5` is a float; a lone `.` is Dot.
                if matches!(self.peek_at(src, 1), Some('0'..='9')) {
                    self.scan_number(src)
                } else {
                    self.bump(src);
                    TokenKind::Dot
                }
            }
