match u64::from_str_radix(hex, 16) {
                    // SQLite hex literals above `i64::MAX` wrap to their
                    // two's-complement value (`0xFFFFFFFFFFFFFFFF` is -1).
                    Ok(n) => TokenKind::Integer(i64::from_ne_bytes(n.to_ne_bytes())),
