                Some('=') => {
                    self.bump(src);
                    TokenKind::Le
                }
                Some('>') => {
                    self.bump(src);
                    TokenKind::Ne
                }
                Some('<') => {
                    self.bump(src);
                    TokenKind::Shl
                }
                _ => TokenKind::Lt,
