            }
            let col_name = where_col(expr)?;
            let index_position = find_leading_index(schema, col_name)?;
            let index = schema.indexes.get(index_position)?;
            let affinity = column_affinity(schema, col_name);
            if !list
                .iter()
                .all(|v| operand_matches_column_affinity(v, affinity))
            {
                return None;
            }
            Some(format!(
                "SEARCH {table_display} USING INDEX {} ({col_name}=?)",
                index.name
            ))
        }
        _ => as_forward_comparison(where_expr).and_then(|(col_name, operand, _inclusive)| {
            if !is_constant_operand(operand, &scope) {
                return None;
            }
            let index_position = find_leading_index(schema, col_name)?;
            let index = schema.indexes.get(index_position)?;
            let affinity = column_affinity(schema, col_name);
            if !operand_matches_column_affinity(operand, affinity) {
                return None;
            }
            // Real sqlite3 collapses inclusive and exclusive into the
            // same `(col>?)` wording (see `try_compile_forward_comparison_seek`'s
            // doc) -- `_inclusive` only matters to the compiled seek's
            // dup-skip, not to this report.
            Some(format!(
                "SEARCH {table_display} USING INDEX {} ({col_name}>?)",
                index.name
            ))
        }),
    }

match &where_expr.kind {
        ExprKind::Between {
            expr,
            lo,
            hi,
            negated: false,
        } => Some((expr, lo, hi, false)),
        ExprKind::Binary {
            op: BinaryOp::Eq,
            lhs,
            rhs,
        } => {
            let (col, lit) = if where_col(lhs).is_some() {
                (lhs.as_ref(), rhs.as_ref())
            } else if where_col(rhs).is_some() {
                (rhs.as_ref(), lhs.as_ref())
            } else {
                return None;
            };
            Some((col, lit, lit, true))
        }
        _ => None,
    }

match parse_select(sql) {
            ParseOutcome::Accepted(s) => *s,
            other => panic!("expected {sql:?} to parse as a SELECT, got {other:?}"),
        }

match parse_update(sql) {
            ParseOutcome::Accepted(u) => *u,
            other => panic!("expected {sql:?} to parse as an UPDATE, got {other:?}"),
        }

match index_ordering_prefix(schema, index, plans) {
        Some((len, forward)) if len == plans.len() => Some(forward),
        _ => None,
    }

match forward {
            None => forward = Some(this_forward),
            Some(f) if f == this_forward => {}
            _ => break,
        }

match &plan.target {
            OrderByTarget::Column(idx) => *idx,
            OrderByTarget::Expr(expr) => {
                let r = compile_value(em, reg, &scope, expr)?;
                key_index(r, first)?
            }
        }

match &join.constraint {
        Some(JoinConstraint::On(e)) => Ok(Some(e.clone())),
        Some(JoinConstraint::Using(cols)) => {
            let (expr, shared) = synthesize_equality_constraint(left, right, &cols[..], true)?;
            if let Some(slot) = dedup_star.get_mut(right_idx) {
                slot.extend(shared);
            }
            Ok(expr)
        }
        None if join.natural => {
            let shared_names: Vec<String> = right
                .schema
                .columns
                .iter()
                .filter(|name| {
                    left.iter().any(|b| {
                        b.schema
                            .columns
                            .iter()
                            .any(|c| c.eq_ignore_ascii_case(name))
                    })
                })
                .cloned()
                .collect();
            if shared_names.is_empty() {
                Ok(None)
            } else {
                let (expr, shared) =
                    synthesize_equality_constraint(left, right, &shared_names, false)?;
                if let Some(slot) = dedup_star.get_mut(right_idx) {
                    slot.extend(shared);
                }
                Ok(expr)
            }
        }
        None => Ok(None),
    }

match plan.checks.as_slice() {
        [check] => check.constraint.as_ref().and_then(|constraint| {
            let prior = exec_bindings.get(..level)?;
            choose_join_access(binding, constraint, prior)
        }),
        _ => None,
    }

match plan.checks.as_slice() {
            [check] => check.constraint.as_ref().and_then(|constraint| {
                let prior = exec_bindings.get(..level)?;
                choose_auto_index_probe(binding, constraint, prior)
            }),
            _ => None,
        }

match single_check_access {
        Some(access) => {
            let scope = join_scope(orig_bindings, null_mask, pos_of, catalog, dedup_star)?;
            let miss = em.new_label();
            match access {
                JoinAccess::Rowid(operand) => {
                    let value_reg = compile_value(em, reg, &scope, &operand)?;
                    let seek_addr =
                        em.emit(Instruction::new(Opcode::SeekRowid, cursor, 0, value_reg));
                    em.patch_p2(seek_addr, miss);
                }
                JoinAccess::UniqueIndex { index, operand } => {
                    let value_reg = compile_value(em, reg, &scope, &operand)?;
                    let index_cursor = i32::try_from(exec_bindings.len().saturating_add(level))
                        .unwrap_or(i32::MAX);
                    let root_page = valid_index_root_page(&index)?;
                    let mut open_instr =
                        Instruction::new(Opcode::OpenRead, index_cursor, root_page, 0);
                    open_instr.p5 = 1;
                    em.emit(open_instr);
                    let leading_collation = index
                        .columns
                        .first()
                        .map_or(Collation::Binary, |c| c.collation);
                    let seek_instr = Instruction::with_p4(
                        Opcode::SeekIndexEq,
                        index_cursor,
                        0,
                        value_reg,
                        P4::SeekKey(vec![leading_collation]),
                    );
                    let seek_addr = em.emit(seek_instr);
                    em.patch_p2(seek_addr, miss);
                    let rowid_reg = reg.alloc();
                    em.emit(Instruction::new(
                        Opcode::IdxRowid,
                        index_cursor,
                        rowid_reg,
                        0,
                    ));
                    let table_seek_addr =
                        em.emit(Instruction::new(Opcode::SeekRowid, cursor, 0, rowid_reg));
                    em.patch_p2(table_seek_addr, miss);
                }
            }
            if let Some(outer_level) = plan.checks.first().and_then(|c| c.sets_matched) {
                let target = matched_regs
                    .get(outer_level)
                    .copied()
                    .flatten()
                    .ok_or_else(|| CodegenError::Unsupported {
                        reason: "join level plan referenced an unallocated matched register"
                            .to_string(),
                    })?;
                em.emit(Instruction::new(Opcode::Integer, 1, target, 0));
            }
            let next_level = level.saturating_add(1);
            compile_join_level_traverse(
                em,
                reg,
                exec_bindings,
                orig_bindings,
                pos_of,
                levels,
                dedup_star,
                null_mask,
                matched_regs,
                next_level,
                catalog,
                leaf,
            )?;
            em.place(miss);
        }
        None if auto_index_probe.is_some() => {
            // #545: build a transient automatic index over `binding`'s
            // join column (a one-time `Once`-guarded pre-pass), then
            // probe it instead of a `Rewind`/`Next` full scan. Unlike a real
            // index's `SeekIndexEq` + recheck-then-`IdxNext` shape
            // (#450), the `AutoIndexSeek`/`AutoIndexRowid`/
            // `AutoIndexNext` primitives are an exact-key multi-map, so
            // there's no leading-column recheck loop needed — every
            // rowid `AutoIndexNext` yields already shares the seeked
            // key by construction.
            //
            // The match arm's own guard already established
            // `auto_index_probe.is_some()`; a nested `match` (rather
            // than an `unreachable!` else-branch) keeps that fact
            // encoded in the type system instead of a runtime panic
            // path, which this crate's macro-vocabulary gate (`make
            // mvl-limit`) doesn't allow outside its curated allowlist.
            let probe = match &auto_index_probe {
                Some(probe) => probe,
                None => {
                    return Err(CodegenError::Unsupported {
                        reason: "unreachable: guarded by the match arm's own is_some() condition"
                            .to_string(),
                    })
                }
            };
            let rewind_end = em.new_label();
            let eph_cursor = reg.alloc_cursor();

            let once_addr = em.emit(Instruction::new(Opcode::Once, 0, 0, 0));
            let after_build = em.new_label();
            let mut open_instr = Instruction::new(Opcode::OpenEphemeral, eph_cursor, 0, 0);
            open_instr.p5 = 2;
            em.emit(open_instr);
            let build_end = em.new_label();
            let build_rewind = em.emit(Instruction::new(Opcode::Rewind, cursor, 0, 0));
            em.patch_p2(build_rewind, build_end);
            let build_loop = em.new_label();
            em.place(build_loop);
            let key_reg = reg.alloc();
            emit_column_read(em, &binding.schema, cursor, probe.key_column, key_reg)?;
            let build_rowid_reg = reg.alloc();
            em.emit(Instruction::new(Opcode::Rowid, cursor, build_rowid_reg, 0));
            let leading_collation = binding
                .schema
                .column_collations
                .get(probe.key_column)
                .copied()
                .unwrap_or(Collation::Binary);
            em.emit(Instruction::with_p4(
                Opcode::AutoIndexInsert,
                eph_cursor,
                key_reg,
                build_rowid_reg,
                P4::SeekKey(vec![leading_collation]),
            ));
            let build_next = em.emit(Instruction::new(Opcode::Next, cursor, 0, 0));
            em.patch_p2(build_next, build_loop);
            em.place(build_end);
            em.place(after_build);
            em.patch_p2(once_addr, after_build);

            let scope = join_scope(orig_bindings, null_mask, pos_of, catalog, dedup_star)?;
            let probe_reg = compile_value(em, reg, &scope, &probe.probe)?;
            let seek_addr = em.emit(Instruction::with_p4(
                Opcode::AutoIndexSeek,
                eph_cursor,
                0,
                probe_reg,
                P4::SeekKey(vec![leading_collation]),
            ));
            em.patch_p2(seek_addr, rewind_end);

            let loop_start = em.new_label();
            em.place(loop_start);

            let skip = em.new_label();
            let idx_rowid_reg = reg.alloc();
            em.emit(Instruction::new(
                Opcode::AutoIndexRowid,
                eph_cursor,
                idx_rowid_reg,
                0,
            ));
            let table_seek_addr = em.emit(Instruction::new(
                Opcode::SeekRowid,
                cursor,
                0,
                idx_rowid_reg,
            ));
            em.patch_p2(table_seek_addr, skip);

            for check in &plan.checks {
                if let Some(constraint) = &check.constraint {
                    let scope = join_scope(orig_bindings, null_mask, pos_of, catalog, dedup_star)?;
                    compile_cond(
                        em,
                        reg,
                        &scope,
                        constraint,
                        CondTargets::null_is_false(Target::Fallthrough, Target::Jump(skip)),
                    )?;
                }
                if let Some(outer_level) = check.sets_matched {
                    let target = matched_regs
                        .get(outer_level)
                        .copied()
                        .flatten()
                        .ok_or_else(|| CodegenError::Unsupported {
                            reason: "join level plan referenced an unallocated matched register"
                                .to_string(),
                        })?;
                    em.emit(Instruction::new(Opcode::Integer, 1, target, 0));
                }
            }
            let next_level = level.saturating_add(1);
            compile_join_level_traverse(
                em,
                reg,
                exec_bindings,
                orig_bindings,
                pos_of,
                levels,
                dedup_star,
                null_mask,
                matched_regs,
                next_level,
                catalog,
                leaf,
            )?;

            em.place(skip);
            let next_addr = em.emit(Instruction::new(Opcode::AutoIndexNext, eph_cursor, 0, 0));
            em.patch_p2(next_addr, loop_start);
            em.place(rewind_end);
        }
        None => {
            let rewind_end = em.new_label();

            let rewind_addr = em.emit(Instruction::new(Opcode::Rewind, cursor, 0, 0));
            em.patch_p2(rewind_addr, rewind_end);
            let loop_start = em.new_label();
            em.place(loop_start);

            let skip = em.new_label();
            for check in &plan.checks {
                if let Some(constraint) = &check.constraint {
                    let scope = join_scope(orig_bindings, null_mask, pos_of, catalog, dedup_star)?;
                    compile_cond(
                        em,
                        reg,
                        &scope,
                        constraint,
                        CondTargets::null_is_false(Target::Fallthrough, Target::Jump(skip)),
                    )?;
                }
                if let Some(outer_level) = check.sets_matched {
                    let target = matched_regs
                        .get(outer_level)
                        .copied()
                        .flatten()
                        .ok_or_else(|| CodegenError::Unsupported {
                            reason: "join level plan referenced an unallocated matched register"
                                .to_string(),
                        })?;
                    em.emit(Instruction::new(Opcode::Integer, 1, target, 0));
                }
            }
            let next_level = level.saturating_add(1);
            compile_join_level_traverse(
                em,
                reg,
                exec_bindings,
                orig_bindings,
                pos_of,
                levels,
                dedup_star,
                null_mask,
                matched_regs,
                next_level,
                catalog,
                leaf,
            )?;
            em.place(skip);
            let next_addr = em.emit(Instruction::new(Opcode::Next, cursor, 0, 0));
            em.patch_p2(next_addr, loop_start);
            em.place(rewind_end);
        }
    }

match access {
                JoinAccess::Rowid(operand) => {
                    let value_reg = compile_value(em, reg, &scope, &operand)?;
                    let seek_addr =
                        em.emit(Instruction::new(Opcode::SeekRowid, cursor, 0, value_reg));
                    em.patch_p2(seek_addr, miss);
                }
                JoinAccess::UniqueIndex { index, operand } => {
                    let value_reg = compile_value(em, reg, &scope, &operand)?;
                    let index_cursor = i32::try_from(exec_bindings.len().saturating_add(level))
                        .unwrap_or(i32::MAX);
                    let root_page = valid_index_root_page(&index)?;
                    let mut open_instr =
                        Instruction::new(Opcode::OpenRead, index_cursor, root_page, 0);
                    open_instr.p5 = 1;
                    em.emit(open_instr);
                    let leading_collation = index
                        .columns
                        .first()
                        .map_or(Collation::Binary, |c| c.collation);
                    let seek_instr = Instruction::with_p4(
                        Opcode::SeekIndexEq,
                        index_cursor,
                        0,
                        value_reg,
                        P4::SeekKey(vec![leading_collation]),
                    );
                    let seek_addr = em.emit(seek_instr);
                    em.patch_p2(seek_addr, miss);
                    let rowid_reg = reg.alloc();
                    em.emit(Instruction::new(
                        Opcode::IdxRowid,
                        index_cursor,
                        rowid_reg,
                        0,
                    ));
                    let table_seek_addr =
                        em.emit(Instruction::new(Opcode::SeekRowid, cursor, 0, rowid_reg));
                    em.patch_p2(table_seek_addr, miss);
                }
            }

match &auto_index_probe {
                Some(probe) => probe,
                None => {
                    return Err(CodegenError::Unsupported {
                        reason: "unreachable: guarded by the match arm's own is_some() condition"
                            .to_string(),
                    })
                }
            }

match col {
            ResultColumn::Star | ResultColumn::TableStar { .. } => {
                for name in &schema.columns {
                    out.push(ResultColumnPlan::Column(name.clone()));
                }
            }
            ResultColumn::Expr { expr, .. } => out.push(ResultColumnPlan::Expr(expr.clone())),
        }

match col {
            ResultColumnPlan::Column(name) => schema
                .columns
                .iter()
                .position(|c| c == name)
                .and_then(|idx| schema.column_collations.get(idx).copied())
                .unwrap_or(Collation::Binary),
            ResultColumnPlan::Expr(expr) => {
                collation_of(expr).unwrap_or_else(|| match &order_by::strip_collate(expr).kind {
                    ExprKind::Column { name, .. } => schema
                        .columns
                        .iter()
                        .position(|c| c == name)
                        .and_then(|idx| schema.column_collations.get(idx).copied())
                        .unwrap_or(Collation::Binary),
                    _ => Collation::Binary,
                })
            }
        }

match col {
            ResultColumnPlan::Column(name) => {
                let idx =
                    column_index(schema, name).ok_or_else(|| CodegenError::UnknownColumn {
                        name: (*name).to_string(),
                    })?;
                let r = reg.alloc();
                if pseudo && schema.rowid_alias == Some(idx) {
                    // `cursor` is a post-`ORDER BY` `OpenPseudo` re-read
                    // of an already-materialized record (see
                    // `compile_sorted_scan`'s pass 1), not a live table
                    // cursor — there is no rowid to fetch via
                    // `Opcode::Rowid` (it isn't a table cursor at all).
                    // Pass 1 built this record via `emit_column_read`
                    // against the *real* cursor, which already resolved
                    // the rowid alias into an ordinary field at this
                    // same position — so a plain `Column` read recovers
                    // it here.
                    em.emit(Instruction::new(
                        Opcode::Column,
                        cursor,
                        i32::try_from(idx).map_err(|_| CodegenError::Unsupported {
                            reason: format!("column index {idx} does not fit in a P2 operand"),
                        })?,
                        r,
                    ));
                } else {
                    // Must go through `emit_column_read`, not a bare
                    // `Column`: this is the `*` / `tbl.*` expansion path, and
                    // an `INTEGER PRIMARY KEY` column is a NULL placeholder
                    // in the record. Emitting `Column` here is why
                    // `SELECT * FROM t` answered NULL for the rowid alias
                    // while `SELECT id FROM t` (which routes through
                    // `compile_value`) answered correctly.
                    emit_column_read(em, schema, cursor, idx, r)?;
                }
                r
            }
            ResultColumnPlan::Expr(expr) => {
                // A bare `name`/`tbl.name` reference — e.g. plain
                // `SELECT id FROM t ORDER BY id` — compiles as an `Expr`
                // here, not the `Column` variant above (that one is
                // reserved for `*`/`tbl.*` expansion), so it needs the
                // same pseudo-cursor rowid-alias special case: `Rowid`
                // only works against a real table cursor, and `cursor`
                // here may be the post-`ORDER BY` pseudo cursor instead.
                // A compound expression that merely *references* the
                // rowid alias (`id + 1`) isn't covered by this — falls
                // through to `compile_value`, matching this crate's
                // existing register-reuse limitations for compound
                // result-column expressions.
                if let ExprKind::Column {
                    name,
                    table: None,
                    catalog: None,
                } = &expr.kind
                {
                    let pseudo_rowid_idx = pseudo
                        .then(|| column_index(schema, name))
                        .flatten()
                        .filter(|idx| schema.rowid_alias == Some(*idx));
                    if let Some(idx) = pseudo_rowid_idx {
                        let r = reg.alloc();
                        em.emit(Instruction::new(
                            Opcode::Column,
                            cursor,
                            i32::try_from(idx).map_err(|_| CodegenError::Unsupported {
                                reason: format!("column index {idx} does not fit in a P2 operand"),
                            })?,
                            r,
                        ));
                        r
                    } else {
                        compile_value(
                            em,
                            reg,
                            &Scope::single_shared(schema, cursor).with_catalog(catalog),
                            expr,
                        )?
                    }
                } else {
                    compile_value(
                        em,
                        reg,
                        &Scope::single_shared(schema, cursor).with_catalog(catalog),
                        expr,
                    )?
                }
            }
        }

let ExprKind::Column {
                    name,
                    table: None,
                    catalog: None,
                } = &expr.kind

match parse_select(sql) {
            ParseOutcome::Accepted(s) => *s,
            other => panic!("expected {sql:?} to parse as a SELECT, got {other:?}"),
        }

match &limit.offset {
        Some(offset_expr) => Some(compile_value(em, reg, scope, offset_expr)?),
        None => None,
    }

match &expr.kind {
        ExprKind::Binary {
            op: BinaryOp::And,
            lhs,
            rhs,
        } => {
            let mut conjuncts = flatten_and_conjuncts(lhs);
            conjuncts.extend(flatten_and_conjuncts(rhs));
            conjuncts
        }
        _ => vec![expr],
    }

match (where_col(lhs), where_col(rhs)) {
            (Some(name), None) if is_supported_seek_operand(rhs) => {
                direct.insert(name.to_ascii_lowercase(), rhs.clone());
            }
            (None, Some(name)) if is_supported_seek_operand(lhs) => {
                direct.insert(name.to_ascii_lowercase(), lhs.clone());
            }
            (Some(a), Some(b)) => {
                column_links.push((a.to_ascii_lowercase(), b.to_ascii_lowercase()));
            }
            _ => {}
        }

match &expr.kind {
        ExprKind::Binary {
            op: BinaryOp::Or,
            lhs,
            rhs,
        } => {
            let mut disjuncts = flatten_or_disjuncts(lhs);
            disjuncts.extend(flatten_or_disjuncts(rhs));
            disjuncts
        }
        _ => vec![expr],
    }

match direct_operand {
        Some(operand) if is_supported_seek_operand(operand) => vec![operand.clone()],
        _ => {
            let constants = propagate_constants(where_expr);
            match resolve_rowid_constant(schema, &constants) {
                Some(value) => vec![value],
                None => {
                    match or_chain_equality_operands(where_expr, |e| is_rowid_reference(schema, e))
                    {
                        Some(or_operands) => or_operands.into_iter().cloned().collect(),
                        None => return Ok(false),
                    }
                }
            }
        }
    }

match resolve_rowid_constant(schema, &constants) {
                Some(value) => vec![value],
                None => {
                    match or_chain_equality_operands(where_expr, |e| is_rowid_reference(schema, e))
                    {
                        Some(or_operands) => or_operands.into_iter().cloned().collect(),
                        None => return Ok(false),
                    }
                }
            }

match or_chain_equality_operands(where_expr, |e| is_rowid_reference(schema, e))
                    {
                        Some(or_operands) => or_operands.into_iter().cloned().collect(),
                        None => return Ok(false),
                    }

match col {
            ResultColumn::Star => out.extend(schema.columns.iter().cloned()),
            ResultColumn::TableStar { table } if table.eq_ignore_ascii_case(&schema.name) => {
                out.extend(schema.columns.iter().cloned());
            }
            ResultColumn::Expr {
                expr:
                    Expr {
                        kind: ExprKind::Column { name, .. },
                        ..
                    },
                ..
            } => out.push(name.clone()),
            _ => return None,
        }

match direct {
        Some(found) => found,
        None => schema
            .indexes
            .iter()
            .enumerate()
            .find_map(|(index_position, idx)| {
                let leading = idx.columns.first()?;
                let matches =
                    |e: &Expr| where_col(e).is_some_and(|n| n.eq_ignore_ascii_case(&leading.name));
                let operands = or_chain_equality_operands(where_expr, matches)?;
                Some((index_position, operands.into_iter().cloned().collect()))
            })?,
    }

match index
                .columns
                .iter()
                .position(|c| c.name.eq_ignore_ascii_case(name))
            {
                Some(col_idx) => em.emit(Instruction::new(
                    Opcode::Column,
                    index_cursor,
                    i32::try_from(col_idx).unwrap_or(0),
                    r,
                )),
                // #535: not one of the index's own columns — must be the
                // rowid-alias column `covers()` (in `find_covering_index`)
                // let through, retrievable from the index leaf's own rowid
                // rather than a declared column.
                None => em.emit(Instruction::new(Opcode::IdxRowid, index_cursor, r, 0)),
            }

super::range_scan::try_compile_between_seek(
        em, reg, select, schema, cursors, end_label, catalog, sink,
    )?

super::range_scan::try_compile_like_prefix_seek(
        em, reg, select, schema, cursors, end_label, catalog, sink,
    )?

super::range_scan::try_compile_in_list_seek(
        em, reg, select, schema, cursors, end_label, catalog, sink,
    )?

super::range_scan::try_compile_forward_comparison_seek(
        em, reg, select, schema, cursors, end_label, catalog, sink,
    )?

try_compile_skip_scan_index(
        em, reg, select, schema, cursors, end_label, catalog, stats, sink,
    )?

match &select.where_clause {
        Some(where_expr) => crate::codegen::row::subquery::hoist_uncorrelated_where_subqueries(
            em, reg, &scope, where_expr,
        )?,
        None => std::collections::HashMap::new(),
    }

match &select.where_clause {
        Some(where_expr) => crate::codegen::row::subquery::memoize_correlated_where_subqueries(
            em, reg, &scope, schema, where_expr,
        ),
        None => std::collections::HashMap::new(),
    }

match &select.where_clause {
        Some(where_expr) => crate::codegen::row::subquery::hoist_uncorrelated_where_subqueries(
            em, reg, &scope, where_expr,
        )?,
        None => std::collections::HashMap::new(),
    }

match &select.where_clause {
        Some(where_expr) => crate::codegen::row::subquery::memoize_correlated_where_subqueries(
            em, reg, &scope, schema, where_expr,
        ),
        None => std::collections::HashMap::new(),
    }

match limit.as_ref() {
        Some(limit_state) if !matches!(select.distinct, Some(Distinctness::Distinct)) => {
            // No OFFSET clause -> offset 0 (SQL default).
            let offset_reg = limit_state.offset_reg.unwrap_or_else(|| {
                let zero = reg.alloc();
                em.emit(Instruction::new(Opcode::Integer, 0, zero, 0));
                zero
            });
            // The grammar only accepts OFFSET inside a LIMIT clause, so a
            // limit state without a limit register is a planner bug, not a
            // bound of "register 0" (db-core#232).
            let limit_reg = limit_state
                .limit_reg
                .ok_or_else(|| CodegenError::Internal {
                    reason: "LIMIT state has an OFFSET register but no LIMIT register".to_string(),
                })?;
            let combined = reg.alloc();
            em.emit(Instruction::new(
                Opcode::OffsetLimit,
                limit_reg,
                combined,
                offset_reg,
            ));
            Some(combined)
        }
        _ => None,
    }

match &plan.target {
            OrderByTarget::Column(idx) => *idx,
            OrderByTarget::Expr(expr) => {
                let r = compile_value(em, reg, &scope, expr)?;
                key_index(r, first)?
            }
        }

match e.kind {
                ExprKind::Literal(Literal::Integer(n)) => n,
                _ => panic!("expected integer literal, got {e:?}"),
            }

match &from.first.kind {
        TableRefKind::Name(_) => {
            let root_page = valid_table_root_page(schema)?;
            em.emit(Instruction::new(
                Opcode::OpenRead,
                cursors.table,
                root_page,
                0,
            ));
        }
        TableRefKind::Subquery(subquery) => {
            crate::codegen::row::subquery::materialize_from_subquery(
                &mut em,
                &mut reg,
                subquery,
                catalog,
                cursors.table,
            )?;
        }
    }

try_compile_index_ordered_group_by(
            em, reg, select, schema, cursors, end_label, catalog, false, sink,
        )?

super::aggregate::try_compile_index_only_count(
            em, reg, select, schema, cursors, catalog, sink,
        )?

super::aggregate::try_compile_direct_agg_scan(
            em, reg, select, schema, cursors, end_label, catalog, sink,
        )?

match col {
            ResultColumn::Star => {
                count = count.saturating_add(schemas.iter().map(|s| s.columns.len()).sum());
            }
            ResultColumn::TableStar { table } => {
                let idx = table_refs
                    .iter()
                    .position(|t| {
                        t.alias
                            .as_deref()
                            .or(t.name())
                            .unwrap_or("")
                            .eq_ignore_ascii_case(table)
                    })
                    .ok_or_else(|| CodegenError::UnknownColumn {
                        name: format!("{table}.*"),
                    })?;
                // `idx` was just found in `table_refs`, which `schemas`
                // mirrors one-to-one; a miss here is a planner bug (#232).
                let n = schemas.get(idx).map(|s| s.columns.len()).ok_or_else(|| {
                    CodegenError::Internal {
                        reason: format!("no schema for FROM item {idx} ({table}.*)"),
                    }
                })?;
                count = count.saturating_add(n);
            }
            ResultColumn::Expr { .. } => count = count.saturating_add(1),
        }

match &first.limit {
        Some(_) => compile_limit_setup(
            &mut em,
            &mut reg,
            &Scope::single(&output_schema, pseudo_cursor),
            first,
        )?,
        None => None,
    }

match select.from.as_ref().map(|from| &from.first.kind) {
            Some(TableRefKind::Subquery(subquery)) => {
                crate::codegen::row::subquery::materialize_from_subquery(
                    em,
                    reg,
                    subquery,
                    catalog,
                    cursors.table,
                )?;
            }
            _ => {
                let root_page = valid_table_root_page(schema)?;
                em.emit(Instruction::new(
                    Opcode::OpenRead,
                    cursors.table,
                    root_page,
                    0,
                ));
            }
        }

match col {
            ResultColumn::Star => {
                for (i, binding) in scope.tables.iter().enumerate() {
                    let suppressed = scope.dedup_star.get(i);
                    for idx in 0..binding.schema.columns.len() {
                        let Some(name) = binding.schema.columns.get(idx) else {
                            continue;
                        };
                        if suppressed.is_some_and(|s| s.contains(&name.to_ascii_lowercase())) {
                            continue;
                        }
                        regs.push(emit_join_column(em, reg, binding, idx)?);
                    }
                }
            }
            ResultColumn::TableStar { table } => {
                let binding = scope
                    .tables
                    .iter()
                    .find(|b| b.matches_qualifier(table))
                    .ok_or_else(|| CodegenError::UnknownColumn {
                        name: format!("{table}.*"),
                    })?;
                for idx in 0..binding.schema.columns.len() {
                    regs.push(emit_join_column(em, reg, binding, idx)?);
                }
            }
            ResultColumn::Expr { expr, .. } => {
                regs.push(compile_value(em, reg, scope, expr)?);
            }
        }

match &expr.kind {
        ExprKind::Column { table, name, .. } => {
            // Result-column aliases take precedence over table columns,
            // same as the single-table path, but only for an
            // unqualified reference.
            if table.is_none() {
                if let Some(ResultColumn::Expr {
                    expr: aliased_expr, ..
                }) = select
                    .columns
                    .iter()
                    .find(|c| matches!(c, ResultColumn::Expr { alias: Some(a), .. } if a == name))
                {
                    return resolve_join_order_by_target(aliased_expr, select, scope);
                }
            }
            let (binding_idx, local_idx) = resolve_scope_column(scope, table.as_deref(), name)?;
            Ok(JoinOrderTarget::Offset(
                joined_column_offset(scope, binding_idx)?.saturating_add(local_idx),
            ))
        }
        _ => Ok(JoinOrderTarget::Expr(expr.clone())),
    }

let Some(ResultColumn::Expr {
                    expr: aliased_expr, ..
                }) = select
                    .columns
                    .iter()
                    .find(|c| matches!(c, ResultColumn::Expr { alias: Some(a), .. } if a == name))

match col {
            ResultColumn::Star => {
                for (i, binding) in scope.tables.iter().enumerate() {
                    let suppressed = scope.dedup_star.get(i);
                    let base = joined_column_offset(scope, i)?;
                    for idx in 0..binding.schema.columns.len() {
                        let Some(name) = binding.schema.columns.get(idx) else {
                            continue;
                        };
                        if suppressed.is_some_and(|s| s.contains(&name.to_ascii_lowercase())) {
                            continue;
                        }
                        regs.push(read_offset(em, reg, base.saturating_add(idx)));
                    }
                }
            }
            ResultColumn::TableStar { table } => {
                let i = scope
                    .tables
                    .iter()
                    .position(|b| b.matches_qualifier(table))
                    .ok_or_else(|| CodegenError::UnknownColumn {
                        name: format!("{table}.*"),
                    })?;
                let base = joined_column_offset(scope, i)?;
                // `i` was just found by name in `scope.tables`, so this
                // lookup cannot miss; an empty expansion would be a bug.
                let count = scope
                    .tables
                    .get(i)
                    .map(|b| b.schema.columns.len())
                    .ok_or_else(|| CodegenError::Internal {
                        reason: format!("binding {i} for {table}.* vanished from scope"),
                    })?;
                for idx in 0..count {
                    regs.push(read_offset(em, reg, base.saturating_add(idx)));
                }
            }
            ResultColumn::Expr {
                expr:
                    Expr {
                        kind: ExprKind::Column { table, name, .. },
                        ..
                    },
                ..
            } => {
                let (binding_idx, local_idx) = resolve_scope_column(scope, table.as_deref(), name)?;
                let abs = joined_column_offset(scope, binding_idx)?.saturating_add(local_idx);
                regs.push(read_offset(em, reg, abs));
            }
            ResultColumn::Expr { .. } => {
                return Err(CodegenError::Unsupported {
                    reason: "ORDER BY combined with a JOIN only supports `*`/`table.*`/bare \
                             column result columns today — a computed expression in the SELECT \
                             list can't yet be re-projected from the sorted output"
                        .to_string(),
                });
            }
        }

match &plan.target {
            JoinOrderTarget::Offset(off) => *off,
            JoinOrderTarget::Expr(expr) => {
                let r = compile_value(em, reg, scope, expr)?;
                key_index(r, first)?
            }
        }

match &expr.kind {
        ExprKind::Collate { expr: inner, .. } | ExprKind::Paren(inner) => strip_collate(inner),
        _ => expr,
    }

match &entry.expr.kind {
                ExprKind::Column { name, .. } => name.clone(),
                _ => format!("column{}", i.saturating_add(1)),
            }

match col {
            ResultColumn::Star | ResultColumn::TableStar { .. } => {
                for name in &schema.columns {
                    out.push(OrderByEntry {
                        expr: Expr {
                            kind: ExprKind::Column {
                                table: None,
                                catalog: None,
                                name: name.clone(),
                            },
                            span: SYNTHETIC_SPAN,
                        },
                        alias: None,
                    });
                }
            }
            ResultColumn::Expr { expr, alias } => out.push(OrderByEntry {
                expr: expr.clone(),
                alias: alias.clone(),
            }),
        }

match &expr.kind {
        ExprKind::Column {
            table: None, name, ..
        } => column_index(schema, name)
            .map(OrderByTarget::Column)
            .ok_or_else(|| CodegenError::UnknownColumn { name: name.clone() }),
        _ => Ok(OrderByTarget::Expr(expr.clone())),
    }

match &expr.kind {
        ExprKind::Literal(Literal::Integer(n)) => {
            let entries = order_by_entries(select, schema);
            let zero_based = usize::try_from(*n)
                .ok()
                .and_then(|ordinal| ordinal.checked_sub(1));
            let entry = zero_based
                .and_then(|zero_based| entries.get(zero_based))
                .ok_or_else(|| CodegenError::Unsupported {
                    reason: format!(
                        "ORDER BY position {n} is out of range for a {}-column result set",
                        entries.len()
                    ),
                })?;
            order_by_target_for_expr(&entry.expr, schema)
        }
        ExprKind::Column {
            table: None, name, ..
        } => {
            // Result-column aliases take precedence over table columns
            // for ORDER BY (unlike WHERE, where aliases aren't visible
            // at all).
            let entries = order_by_entries(select, schema);
            if let Some(entry) = entries
                .iter()
                .find(|e| e.alias.as_deref() == Some(name.as_str()))
            {
                return order_by_target_for_expr(&entry.expr, schema);
            }
            column_index(schema, name)
                .map(OrderByTarget::Column)
                .ok_or_else(|| CodegenError::UnknownColumn { name: name.clone() })
        }
        _ => order_by_target_for_expr(expr, schema),
    }

match self {
            EmitError::Parse(e) => write!(f, "{e}"),
            EmitError::Unsupported(what) => write!(f, "codegen does not support {what} yet"),
            EmitError::Plan(e) => write!(f, "{e}"),
        }

match c {
        ResultColumn::Expr {
            expr:
                AstExpr {
                    kind: ExprKind::FunctionCall { tail, .. },
                    ..
                },
            ..
        } => matches!(tail.as_deref(), Some(t) if t.over.is_some()),
        _ => false,
    }

match &select.where_clause {
        Some(AstExpr {
            kind:
                ExprKind::InSubquery {
                    expr,
                    subquery,
                    negated: false,
                },
            ..
        }) if matches!(expr.kind, ExprKind::Column { .. }) => Some(subquery),
        _ => None,
    }

match &from.first.kind {
        TableRefKind::Name(name) => Ok(name),
        // The grammar requires the alias; emitting `""` as a table name
        // would produce a program that can never bind a file (db-core#232).
        TableRefKind::Subquery(_) => from
            .first
            .alias
            .as_deref()
            .ok_or(EmitError::Unsupported("a FROM subquery without an alias")),
    }

match &instruction.comment {
            Some(comment) => {
                let _ = writeln!(
                    out,
                    "    {}, // {}",
                    render_opcode(&instruction.opcode),
                    comment.replace('\n', " ")
                );
            }
            None => {
                let _ = writeln!(out, "    {},", render_opcode(&instruction.opcode));
            }
        }

match s {
        Some(s) => format!("Some({}.to_string())", rust_str_literal(s)),
        None => "None".to_string(),
    }

match kind {
        TableRefKind::Name(name) => {
            format!("TableRefKind::Name({}.to_string())", rust_str_literal(name))
        }
        TableRefKind::Subquery(select) => {
            format!(
                "TableRefKind::Subquery(Box::new({}))",
                render_select(select)
            )
        }
    }

match constraint {
        JoinConstraint::On(expr) => format!("JoinConstraint::On({})", render_expr(expr)),
        JoinConstraint::Using(cols) => format!(
            "JoinConstraint::Using(vec![{}])",
            cols.iter()
                .map(|c| format!("{}.to_string()", rust_str_literal(c)))
                .collect::<Vec<_>>()
                .join(", ")
        ),
    }

match col {
        ResultColumn::Star => "ResultColumn::Star".to_string(),
        ResultColumn::TableStar { table } => format!(
            "ResultColumn::TableStar {{ table: {}.to_string() }}",
            rust_str_literal(table)
        ),
        ResultColumn::Expr { expr, alias } => format!(
            "ResultColumn::Expr {{ expr: {}, alias: {} }}",
            render_expr(expr),
            render_option_str(alias.as_deref())
        ),
    }

match kind {
        ExprKind::Literal(lit) => format!("ExprKind::Literal({})", render_literal(lit)),
        ExprKind::Column {
            table,
            catalog,
            name,
        } => format!(
            "ExprKind::Column {{ table: {}, catalog: {}, name: {}.to_string() }}",
            render_option_str(table.as_deref()),
            render_option_str(catalog.as_deref()),
            rust_str_literal(name)
        ),
        ExprKind::FunctionCall {
            name,
            distinct,
            args,
            tail,
        } => format!(
            "ExprKind::FunctionCall {{ name: {}.to_string(), distinct: {distinct}, args: {}, tail: {} }}",
            rust_str_literal(name),
            render_function_args(args),
            match tail {
                // `range` (#308) is stream-only: `codegen::batch` never
                // plans a call carrying one (rejected upstream, same as
                // `Select::scope`), so this emits a literal `None` rather
                // than rendering `t.range` at all.
                Some(t) => format!(
                    "Some(Box::new(FunctionTail {{ filter: {}, over: {}, range: None }}))",
                    match &t.filter {
                        Some(f) => format!("Some({})", render_expr(f)),
                        None => "None".to_string(),
                    },
                    match &t.over {
                        Some(w) => format!("Some({})", render_window_def(w)),
                        None => "None".to_string(),
                    }
                ),
                None => "None".to_string(),
            }
        ),
        ExprKind::Unary { op, expr } => {
            format!("ExprKind::Unary {{ op: UnaryOp::{}, expr: Box::new({}) }}", render_unary_op(*op), render_expr(expr))
        }
        ExprKind::Binary { op, lhs, rhs } => format!(
            "ExprKind::Binary {{ op: BinaryOp::{}, lhs: Box::new({}), rhs: Box::new({}) }}",
            render_binary_op(*op),
            render_expr(lhs),
            render_expr(rhs)
        ),
        ExprKind::Is { lhs, rhs, negated } => format!(
            "ExprKind::Is {{ lhs: Box::new({}), rhs: Box::new({}), negated: {negated} }}",
            render_expr(lhs),
            render_expr(rhs)
        ),
        ExprKind::IsNull { expr, negated } => format!(
            "ExprKind::IsNull {{ expr: Box::new({}), negated: {negated} }}",
            render_expr(expr)
        ),
        ExprKind::Paren(inner) => format!("ExprKind::Paren(Box::new({}))", render_expr(inner)),
        ExprKind::InSubquery {
            expr,
            subquery,
            negated,
        } => format!(
            "ExprKind::InSubquery {{ expr: Box::new({}), subquery: Box::new({}), negated: {negated} }}",
            render_expr(expr),
            render_select(subquery)
        ),
        ExprKind::Exists { subquery, negated } => format!(
            "ExprKind::Exists {{ subquery: Box::new({}), negated: {negated} }}",
            render_select(subquery)
        ),
        // Not part of the batch planner's validated subset -- `generate`
        // never plans a query containing these, so no renderer feeds
        // this arm today. Not a feature gap to silently paper over: once
        // a real caller needs one of these, this arm should become a
        // real render, not before.
        ExprKind::Param(_)
        | ExprKind::Between { .. }
        | ExprKind::In { .. }
        | ExprKind::Like { .. }
        | ExprKind::Case { .. }
        | ExprKind::Cast { .. }
        | ExprKind::Collate { .. }
        | ExprKind::Subquery(_)
        | ExprKind::InSubqueryMulti { .. } => {
            // Rendered as a `compile_error!` in the *generated* source, so
            // if a planner ever does feed one of these here the consumer's
            // build fails loudly with the exact shape -- rather than this
            // emitter panicking (an `unreachable!` the qualified subset
            // forbids) or silently emitting a fake rendering.
            format!(
                "compile_error!(\"db-core emit does not yet render {}\")",
                format!("{kind:?}").replace('"', "'")
            )
        }
    }

match op {
        UnaryOp::Not => "Not",
        UnaryOp::Plus => "Plus",
        UnaryOp::Minus => "Minus",
        UnaryOp::BitNot => "BitNot",
    }

match op {
        Opcode::LoadColumn { reg, column } => format!(
            "Opcode::LoadColumn {{ reg: {reg}, column: std::borrow::Cow::Borrowed({}) }}",
            rust_str_literal(column)
        ),
        Opcode::LoadConst { reg, value } => format!(
            "Opcode::LoadConst {{ reg: {reg}, value: {} }}",
            render_value(value)
        ),
        Opcode::Map { dst, op, a, b } => format!(
            "Opcode::Map {{ dst: {dst}, op: MapOp::{}, a: {a}, b: {b} }}",
            render_map_op(*op)
        ),
        Opcode::Filter { predicate } => format!("Opcode::Filter {{ predicate: {predicate} }}"),
        Opcode::Reduce { func, src, dst } => format!(
            "Opcode::Reduce {{ func: AggFunc::{}, src: {}, dst: {dst} }}",
            render_agg_func(*func),
            render_option_usize(*src)
        ),
        Opcode::GroupReduce {
            group_by,
            aggs,
            agg_dst,
        } => {
            let group_by = render_usize_slice(group_by);
            let agg_dst = render_usize_slice(agg_dst);
            let aggs: Vec<String> = aggs
                .iter()
                .map(|(f, s)| {
                    format!(
                        "(AggFunc::{}, {})",
                        render_agg_func(*f),
                        render_option_usize(*s)
                    )
                })
                .collect();
            format!("Opcode::GroupReduce {{ group_by: std::borrow::Cow::Borrowed(&{group_by}), aggs: std::borrow::Cow::Borrowed(&[{}]), agg_dst: std::borrow::Cow::Borrowed(&{agg_dst}) }}", aggs.join(", "))
        }
        Opcode::Scan => "Opcode::Scan".to_string(),
        Opcode::Emit { registers } => format!(
            "Opcode::Emit {{ registers: std::borrow::Cow::Borrowed(&{}) }}",
            render_usize_slice(registers)
        ),
        Opcode::NextSegment { loop_start } => {
            format!("Opcode::NextSegment {{ loop_start: {loop_start} }}")
        }
        Opcode::Halt => "Opcode::Halt".to_string(),
        Opcode::Combine {
            agg_parts,
            num_group_keys,
            distinct,
        } => {
            let parts: Vec<String> = agg_parts.iter().map(render_agg_part).collect();
            format!(
                "Opcode::Combine {{ agg_parts: std::borrow::Cow::Borrowed(&[{}]), num_group_keys: {num_group_keys}, distinct: {distinct} }}",
                parts.join(", "),
            )
        }
        Opcode::Sort { col, descending } => {
            format!("Opcode::Sort {{ col: {col}, descending: {descending} }}")
        }
        Opcode::Limit { n } => format!("Opcode::Limit {{ n: {n} }}"),
        // No caller-side planner emits these three yet -- the join/semi-
        // join/window bypass shapes ([`render_joined`]/
        // [`render_semi_join`]/[`render_windowed`]) still reconstruct a
        // `Select` literal instead of a `const PROGRAM` for those cases
        // (see this module's top doc comment), so no flat program this
        // module renders contains them. Not a feature gap to silently
        // paper over with a fake rendering: once a real planner starts
        // emitting these, this arm should become a real render_*
        // implementation at that point, not before.
        Opcode::HashBuild { .. }
        | Opcode::HashProbe { .. }
        | Opcode::Window { .. }
        | Opcode::Call { .. } => {
            // Same `compile_error!`-in-generated-source strategy as
            // `render_expr_kind`'s unsupported arm: loud at the consumer's
            // build, no panic here.
            format!(
                "compile_error!(\"db-core emit does not yet render {}\")",
                format!("{op:?}").replace('"', "'")
            )
        }
    }

match value {
        Value::Int(v) => format!("Value::Int({v})"),
        Value::Float(v) => format!("Value::Float({v:?})"),
        Value::Bool(v) => format!("Value::Bool({v})"),
        Value::Str(v) => format!(
            "Value::Str(std::borrow::Cow::Borrowed({}))",
            rust_str_literal(v)
        ),
        Value::Null => "Value::Null".to_string(),
    }

match self.on_null {
                NullTarget::True => NullTarget::False,
                NullTarget::False => NullTarget::True,
            }

match self.resolve_own(table, name) {
            Ok(v) => Ok(v),
            Err(own_err) => match &self.outer {
                Some(outer) => outer.resolve(table, name),
                None => Err(own_err),
            },
        }

match &self.outer {
                Some(outer) => outer.resolve(table, name),
                None => Err(own_err),
            }

match self.file.refresh() {
                Ok(Refresh::New(blocks)) => {
                    let observed = now_ns();
                    let mut sealed: Vec<Arc<Segment>> = Vec::new();
                    for b in &blocks {
                        for s in Segment::seal_block(b, &self.source, &self.parser, observed) {
                            sealed.push(Arc::new(s));
                        }
                    }
                    // One batch per call: concatenate the sealed segments.
                    let total: usize = sealed.iter().map(|s| s.len()).sum();
                    let mut merged = Batch::new(total);
                    for req in &self.columns {
                        let mut values: Vec<Value> = Vec::with_capacity(total);
                        for s in &sealed {
                            values.extend(column_values(s, &req.name)?);
                        }
                        merged = merged.with_column(req.key.clone(), values);
                    }
                    self.last_sealed = sealed;
                    return Some(merged);
                }
                Ok(Refresh::Truncated) => {
                    // Rotation: keep following the new file from its end.
                    idle = 0;
                }
                Ok(Refresh::NoNew) => {
                    if let Some(max) = self.max_idle_polls {
                        if idle >= max {
                            return None;
                        }
                    }
                    idle = idle.saturating_add(1);
                    std::thread::sleep(self.poll);
                }
                Err(_) => return None,
            }

match std::str::from_utf8(line) {
            Ok(s) => s.trim_end_matches(['\r', '\n']),
            Err(_) => {
                batch.push_line(line, None, None, None, None);
                return;
            }
        }

match alias::classify(key) {
