match page_size("compressed_page_size", -1) {
            Err(FileError::InvalidMetadata { field, value }) => {
                assert_eq!(field, "compressed_page_size");
                assert_eq!(value, -1);
            }
            other => panic!("expected InvalidMetadata, got {other:?}"),
        }

match self {
            NestedError::MissingLeafData(path) => {
                write!(f, "no decoded data for leaf column '{path}'")
            }
            NestedError::UnsupportedListElement(path) => write!(
                f,
                "list element at '{path}' is not a supported shape (scalar or flat struct)"
            ),
            NestedError::UnsupportedMapShape(path) => write!(
                f,
                "MAP at '{path}' does not have the expected key_value(key, value) shape"
            ),
        }

match self {
            SnappyError::UnexpectedEof => write!(f, "unexpected end of snappy input"),
            SnappyError::InvalidVarint => write!(f, "invalid snappy varint"),
            SnappyError::InvalidLength(n) => write!(f, "declared snappy length out of range: {n}"),
            SnappyError::InvalidCopyOffset => write!(
                f,
                "snappy copy references data before the start of the buffer"
            ),
            SnappyError::SizeMismatch { expected, actual } => {
                write!(
                    f,
                    "snappy decompressed size mismatch: expected {expected}, got {actual}"
                )
            }
        }

match tag & 0x03 {
            0 => {
                // Literal: length encoded in the tag's upper 6 bits, or
                // in 1-4 following little-endian bytes when that field
                // is >= 60 (tag value 60+n means "length follows in the
                // next n+1 bytes").
                let len_tag = (tag >> 2) as usize;
                let len = if len_tag < 60 {
                    len_tag + 1
                } else {
                    let extra_bytes = len_tag - 59;
                    let mut len = 0usize;
                    for i in 0..extra_bytes {
                        let b = *data.get(pos + i).ok_or(SnappyError::UnexpectedEof)?;
                        len |= (b as usize) << (8 * i);
                    }
                    pos += extra_bytes;
                    len + 1
                };
                let bytes = data.get(pos..pos + len).ok_or(SnappyError::UnexpectedEof)?;
                out.extend_from_slice(bytes);
                pos += len;
            }
            1 => {
                // Copy with 1-byte offset: length in bits 2-4 (+4), offset
                // is 3 bits from the tag (top) plus 1 following byte.
                let len = ((tag >> 2) & 0x07) as usize + 4;
                let offset_hi = ((tag >> 5) & 0x07) as usize;
                let offset_lo = *data.get(pos).ok_or(SnappyError::UnexpectedEof)? as usize;
                pos += 1;
                let offset = (offset_hi << 8) | offset_lo;
                copy_from_offset(&mut out, offset, len)?;
            }
            2 => {
                // Copy with 2-byte little-endian offset, length in the
                // tag's upper 6 bits (+1).
                let len = (tag >> 2) as usize + 1;
                let lo = *data.get(pos).ok_or(SnappyError::UnexpectedEof)? as usize;
                let hi = *data.get(pos + 1).ok_or(SnappyError::UnexpectedEof)? as usize;
                pos += 2;
                let offset = lo | (hi << 8);
                copy_from_offset(&mut out, offset, len)?;
            }
            _ => {
                // Copy with 4-byte little-endian offset (tag & 0x03 == 3).
                let len = (tag >> 2) as usize + 1;
                let bytes: [u8; 4] = data
                    .get(pos..pos + 4)
                    .and_then(|b| b.try_into().ok())
                    .ok_or(SnappyError::UnexpectedEof)?;
                let offset = u32::from_le_bytes(bytes) as usize;
                pos += 4;
                copy_from_offset(&mut out, offset, len)?;
            }
        }

match self {
            ZstdError::Frame(e) => write!(f, "zstd frame error: {e}"),
            ZstdError::Read(e) => write!(f, "zstd read error: {e}"),
            ZstdError::SizeMismatch { expected, actual } => {
                write!(
                    f,
                    "zstd decompressed size mismatch: expected {expected}, got {actual}"
                )
            }
        }

match self {
            FooterError::FileTooShort => write!(f, "file too short to contain a Parquet footer"),
            FooterError::BadMagic => write!(f, "missing PAR1 magic bytes"),
            FooterError::Thrift(e) => write!(f, "failed to decode footer metadata: {e}"),
        }

match v {
            0 => Repetition::Required,
            1 => Repetition::Optional,
            2 => Repetition::Repeated,
            other => Repetition::Unknown(other),
        }

match v {
            5 => ConvertedType::Decimal,
            9 => ConvertedType::TimestampMillis,
            10 => ConvertedType::TimestampMicros,
            other => ConvertedType::Other(other),
        }

match v {
            0 => Codec::Uncompressed,
            1 => Codec::Snappy,
            6 => Codec::Zstd,
            other => Codec::Other(other),
        }

match self {
            ReadError::Encoding(e) => write!(f, "{e}"),
            ReadError::UnexpectedEof => write!(f, "unexpected end of page data"),
            ReadError::InvalidValueCount(n) => write!(f, "invalid page value count: {n}"),
            ReadError::InvalidUtf8 => write!(f, "BYTE_ARRAY value is not valid UTF-8"),
            ReadError::DictionaryIndexOutOfRange(i) => {
                write!(f, "dictionary index {i} out of range")
            }
            ReadError::UnsupportedNestedPhysicalType(t) => {
                write!(f, "unsupported physical type in a nested column: {t:?}")
            }
        }

match physical_type {
        PhysicalType::Int32 => Ok(LeafScalar::Int32(read_plain_i32(buf)?)),
        PhysicalType::Int64 => Ok(LeafScalar::Int64(read_plain_i64(buf)?)),
        PhysicalType::Float => Ok(LeafScalar::Float(read_plain_f32(buf)?)),
        PhysicalType::Double => Ok(LeafScalar::Double(read_plain_f64(buf)?)),
        PhysicalType::ByteArray => Ok(LeafScalar::Str(read_plain_string(buf)?)),
        PhysicalType::Boolean => {
            let byte = *buf.first().ok_or(ReadError::UnexpectedEof)?;
            let bit = (byte >> (*bit_pos % 8)) & 1;
            *bit_pos += 1;
            if (*bit_pos).is_multiple_of(8) {
                *buf = &buf[1..];
            }
            Ok(LeafScalar::Bool(bit == 1))
        }
        other => Err(ReadError::UnsupportedNestedPhysicalType(other)),
    }

match self {
            ThriftError::UnexpectedEof => write!(f, "unexpected end of input"),
            ThriftError::InvalidVarint => write!(f, "varint too long"),
            ThriftError::InvalidLength(n) => write!(f, "length or size out of range: {n}"),
            ThriftError::UnknownType(t) => write!(f, "unknown thrift compact type: 0x{t:02x}"),
        }

match bool_value {
                Some(v) => Ok(Value::Bool(v)),
                None => Ok(Value::Bool(self.read_byte()? == CTYPE_BOOLEAN_TRUE)),
            }

match ctype {
                CTYPE_BOOLEAN_TRUE => Some(true),
                CTYPE_BOOLEAN_FALSE => Some(false),
                _ => None,
            }

match nibble {
        0x01 => Ok(CTYPE_BOOLEAN_TRUE), // bool element; value bit follows as a real byte via read_bool path
        CTYPE_BYTE | CTYPE_I16 | CTYPE_I32 | CTYPE_I64 | CTYPE_DOUBLE | CTYPE_BINARY
        | CTYPE_LIST | CTYPE_SET | CTYPE_MAP | CTYPE_STRUCT => Ok(nibble),
        other => Err(ThriftError::UnknownType(other)),
    }

match &fields[0].1 {
            Value::Struct(inner_fields) => {
                assert_eq!(inner_fields, &vec![(1, Value::Bool(true))]);
            }
            other => panic!("expected nested struct, got {other:?}"),
        }

match &fields[0].1 {
            Value::Map(entries) => {
                assert_eq!(entries.len(), 1);
                assert_eq!(entries[0].0.as_str(), Some("a"));
                assert_eq!(entries[0].1, Value::I32(1));
            }
            other => panic!("expected map, got {other:?}"),
        }

match self {
            MmapRegion::Mapped(m) => m,
            MmapRegion::Owned(b) => b,
        }

match bytes.iter().position(|&b| b == 0) {
        Some(i) => bytes.get(..i).unwrap_or(bytes).to_vec(),
        None => bytes.to_vec(),
    }

match v {
        Value::Null => {}
        Value::Integer(i) => buf.extend_from_slice(i.to_string().as_bytes()),
        Value::Real(r) => buf.extend_from_slice(format_real(*r).as_bytes()),
        Value::Text(s) => write_truncated_at_nul(buf, s.as_bytes()),
        Value::Blob(b) => write_truncated_at_nul(buf, b),
    }

match bytes.iter().position(|&b| b == 0) {
        Some(i) => bytes.get(..i).unwrap_or(bytes),
        None => bytes,
    }

match v {
        Value::Null => {}
        Value::Integer(i) => buf.push_str(&i.to_string()),
        Value::Real(r) => buf.push_str(&format_real(*r)),
        Value::Text(s) => buf.push_str(&csv_quote(s)),
        Value::Blob(b) => buf.push_str(&csv_quote(&format_blob(b))),
