match source.raw_os_error() {
        Some(EAGAIN) | Some(EACCES) => VfsError::Locked {
            path: path.display().to_string(),
        },
        _ => to_vfs_error(path, source),
    }

match self.files.lock() {
            Ok(files) => files,
            Err(_) => return,
        }

match vfs.open_read(Path::new("/x")) {
            Ok(_) => panic!("expected an error"),
            Err(e) => e,
        }

match err {
            VfsError::Io { path, .. } => assert_eq!(path, "/x"),
            other => panic!("expected Io error, got {other:?}"),
        }

match err {
            VfsError::Io { path, .. } => assert_eq!(path, "/y"),
            other => panic!("expected Io error, got {other:?}"),
        }

match source.raw_os_error() {
        Some(EAGAIN) | Some(EACCES) => VfsError::Locked {
            path: path.display().to_string(),
        },
        _ => to_shm_vfs_error(path, source),
    }

match fcntl_lock(&file, F_WRLCK, byte, 1) {
            Ok(()) => {
                fcntl_lock(&file, F_UNLCK, byte, 1)?;
            }
            Err(e) if matches!(e.raw_os_error(), Some(EAGAIN) | Some(EACCES)) => {
                marks.push(read_mark(&file, slot)?);
            }
            Err(e) => return Err(e),
        }

match open_shm_shared(shm_path) {
        Ok(file) => file,
        Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(None),
        Err(e) => return Err(e),
    }

match fcntl_lock(&file, F_WRLCK, byte, 1) {
            Ok(()) => {
                set_read_mark(&file, slot, mx_frame(&file)?)?;
                fcntl_lock(&file, F_RDLCK, byte, 1)?;
                return Ok(Some(WalReadLock { file, slot }));
            }
            Err(e) if matches!(e.raw_os_error(), Some(EAGAIN) | Some(EACCES)) => {
                last_err = Some(e);
            }
            Err(e) => return Err(e),
        }

match result {
            Err(VfsError::Locked { .. }) => {}
            other => panic!("expected VfsError::Locked, got {other:?}"),
        }

match self {
            PageError::InvalidPageNumber => write!(f, "invalid page number 0"),
            PageError::ShortRead {
                page_num,
                expected,
                got,
