match self {
            PageError::Vfs(source) => Some(source),
            PageError::InvalidPageNumber
            | PageError::ShortRead { .. }
            | PageError::WrongLength { .. } => None,
        }

match source.read_page(1) {
            Err(PageError::ShortRead {
                page_num,
                expected,
                got,
            }) => {
                assert_eq!(page_num, 1);
                assert_eq!(expected, 16);
                assert_eq!(got, 8);
