match vfs.open_read(Path::new("/missing")) {
            Err(e) => e,
            Ok(_) => panic!("expected open_read to fail for a missing file"),
        }

match source.write_page(1, &[0u8; 8]) {
            Err(PageError::WrongLength {
                page_num,
                expected,
                got,
            }) => {
                assert_eq!(page_num, 1);
                assert_eq!(expected, 16);
                assert_eq!(got, 8);
            }
            other => panic!("expected WrongLength, got {other:?}"),
        }

match arg {
            FcntlArg::F_SETLK(fl) => fcntl(fd, F_SETLK, fl as *const flock),
            FcntlArg::F_SETLKW(fl) => fcntl(fd, F_SETLKW, fl as *const flock),
            FcntlArg::F_GETLK(fl) => fcntl(fd, F_GETLK, fl as *mut flock),
        }

match self.level {
            LockLevel::Unlocked => {
                // `os_unix.c`'s `unixLock`: a plain fcntl read lock on
                // SHARED_FIRST wouldn't itself conflict with a writer's
                // PENDING_BYTE write lock (different byte ranges), so a
                // new reader must explicitly probe PENDING_BYTE first —
                // that's what actually stops a new SHARED lock from
                // starting once a writer is mid-ladder.
                fcntl_lock(&self.file, F_RDLCK, PENDING_BYTE, 1)?;
                fcntl_lock(&self.file, F_UNLCK, PENDING_BYTE, 1)?;
                fcntl_lock(&self.file, F_RDLCK, SHARED_FIRST, SHARED_SIZE)?;
                self.level = LockLevel::Shared;
            }
            LockLevel::Shared => {
                fcntl_lock(&self.file, F_WRLCK, RESERVED_BYTE, 1)?;
                self.level = LockLevel::Reserved;
            }
            LockLevel::Reserved => {
                fcntl_lock(&self.file, F_WRLCK, PENDING_BYTE, 1)?;
                self.level = LockLevel::Pending;
            }
            LockLevel::Pending => {
                fcntl_lock(&self.file, F_WRLCK, SHARED_FIRST, SHARED_SIZE)?;
                self.level = LockLevel::Exclusive;
            }
            LockLevel::Exclusive => {}
        }

match self.level {
            LockLevel::Exclusive => {
                // Downgrade the SHARED range back to a read lock rather
                // than dropping it — PENDING is still held below, so this
                // stays a real ladder level (Pending), not a gap.
                fcntl_lock(&self.file, F_RDLCK, SHARED_FIRST, SHARED_SIZE)?;
                self.level = LockLevel::Pending;
            }
            LockLevel::Pending => {
                fcntl_lock(&self.file, F_UNLCK, PENDING_BYTE, 1)?;
                self.level = LockLevel::Reserved;
            }
            LockLevel::Reserved => {
                fcntl_lock(&self.file, F_UNLCK, RESERVED_BYTE, 1)?;
                self.level = LockLevel::Shared;
            }
            LockLevel::Shared => {
                fcntl_lock(&self.file, F_UNLCK, SHARED_FIRST, SHARED_SIZE)?;
                self.level = LockLevel::Unlocked;
            }
            LockLevel::Unlocked => {}
        }

match result {
            Err(VfsError::Locked { .. }) => {}
            Err(other) => panic!("expected VfsError::Locked, got {other:?}"),
            Ok(_) => panic!("expected VfsError::Locked, got Ok"),
        }

match self {
            #[allow(
                clippy::indexing_slicing,
                reason = "start/len are computed from a validated in-bounds slice at construction (reassemble_payload)"
            )]
            Payload::Local { page, start, len } => &page[*start..start.saturating_add(*len)],
            Payload::Owned(bytes) => bytes,
        }

match page_type {
                LEAF_TABLE => {
                    let cell_ptr_base = header_start.saturating_add(8);
                    // Leaf cells are stored in rowid-ascending order by
                    // pointer-array index (see the module's ordering
                    // invariant), so a binary search over `i` decodes only
                    // O(log n) cells instead of scanning every cell on the
                    // page — this matters a lot for repeated seeks (e.g. a
                    // join probing the same small table per outer row).
                    let mut lo = 0usize;
                    let mut hi = num_cells;
                    while lo < hi {
                        let mid = lo.saturating_add(hi.saturating_sub(lo) / 2);
                        let cell_start = read_cell_pointer(
                            &page,
                            cell_ptr_offset(cell_ptr_base, mid),
                            page_num,
                            mid,
                        )?;
                        let (rowid, payload_len, tail_start) =
                            decode_cell_head(&page, cell_start, page_num)?;
                        match rowid.cmp(&target_rowid) {
                            std::cmp::Ordering::Equal => {
                                self.current = Some(CurrentCell {
                                    page: Rc::clone(&page),
                                    page_num,
                                    tail_start,
                                    payload_len,
                                });
                                return Ok(Some(rowid));
                            }
                            std::cmp::Ordering::Less => lo = mid.saturating_add(1),
                            std::cmp::Ordering::Greater => hi = mid,
                        }
                    }
                    return Ok(None);
                }
                INTERIOR_TABLE => {
                    require_interior_header(&page, header_start, page_num)?;
                    let cell_ptr_base = header_start.saturating_add(12);
                    let rightmost = read_u32(&page, header_start.saturating_add(8), page_num)?;
                    // Interior separator keys are ascending by pointer-array
                    // index too; binary search for the leftmost `i` with
                    // `target_rowid <= key(i)` (the child to descend into),
                    // falling back to `rightmost` when none qualifies —
                    // same semantics as the old early-break linear scan.
                    let mut lo = 0usize;
                    let mut hi = num_cells;
                    let mut next_page = rightmost;
                    while lo < hi {
                        let mid = lo.saturating_add(hi.saturating_sub(lo) / 2);
                        let cell_start = read_cell_pointer(
                            &page,
                            cell_ptr_offset(cell_ptr_base, mid),
                            page_num,
                            mid,
                        )?;
                        let key_bytes = page.get(cell_start.saturating_add(4)..).ok_or({
                            BtreeError::InvalidCellPointer {
                                page_num,
                                index: mid,
                            }
                        })?;
                        let (key, _) = decode_varint(key_bytes)
                            .map_err(|source| BtreeError::InvalidCellVarint { page_num, source })?;
