            other => panic!("expected text, got {other:?}"),
        }

match v {
            Value::Integer(i) => *i,
            other => panic!("expected integer, got {other:?}"),
        }

match &row.payload {
            Payload::Local { page, .. } => {
                assert!(
                    Rc::strong_count(page) >= 2,
                    "expected the row to share the page's Rc, not hold the only reference"
                );
            }
            Payload::Owned(_) => panic!("expected a borrowed Local payload, got an Owned copy"),
        }

match entries.iter().position(|(child, _)| *child == emptied_page) {
        Some(idx) => {
            entries.remove(idx);
        }
        None if rightmost == emptied_page => {
            let Some((last_child, _)) = entries.pop() else {
                return Err(BtreeError::Internal(
                    "interior page's rightmost pointer was emptied but it has no routing entries to promote",
                ));
            };
            rightmost = last_child;
        }
        None => {
            return Err(BtreeError::MissingChildRoute {
                page_num: parent_page,
                child: emptied_page,
            });
        }
    }

match entries.iter_mut().find(|(child, _)| *child == old_child) {
        Some(entry) => entry.0 = new_child,
        None if rightmost == old_child => rightmost = new_child,
        None => {
            return Err(BtreeError::MissingChildRoute {
                page_num: parent_page,
                child: old_child,
            })
        }
    }

match page_type {
        LEAF_TABLE => {
            let cells = collect_leaf_cells(&content, child_header_start, only_child, usable_size)?;
            let dest = pager.get_page_mut(root_page)?;
            write_leaf_page(dest, root_header_start, root_page, &cell_bytes(cells))?;
        }
        INTERIOR_TABLE => {
            let (entries, rightmost) =
                collect_interior_entries(&content, child_header_start, only_child)?;
            let cells: Vec<Vec<u8>> = entries
                .iter()
                .map(|(child, key)| build_interior_cell(*child, *key))
                .collect();
            let dest = pager.get_page_mut(root_page)?;
            write_interior_page(dest, root_header_start, root_page, &cells, rightmost)?;
        }
        other => {
            return Err(BtreeError::UnexpectedPageType {
                page_num: only_child,
                page_type: other,
            })
        }
    }

match entries.iter().position(|(child, _)| *child == old_page) {
        Some(idx) => {
            entries.insert(idx, (old_page, divider));
            let successor = entries
                .get_mut(idx.saturating_add(1))
                .ok_or(BtreeError::Internal(
                    "split successor entry must exist right after insertion",
                ))?;
            successor.0 = new_page;
        }
        None if rightmost == old_page => {
            entries.push((old_page, divider));
            rightmost = new_page;
        }
        None => {
            return Err(BtreeError::MissingChildRoute {
                page_num: parent_page,
                child: old_page,
            });
        }
    }

match page_type {
        LEAF_TABLE => {
            let cells = collect_leaf_cells(&content, header_start_root, root_page, usable_size)?;
            let dest = pager.get_page_mut(relocated)?;
            write_leaf_page(dest, 0, relocated, &cell_bytes(cells))?;
        }
        INTERIOR_TABLE => {
            let (entries, rightmost) =
                collect_interior_entries(&content, header_start_root, root_page)?;
            let cells: Vec<Vec<u8>> = entries
                .iter()
                .map(|(child, key)| build_interior_cell(*child, *key))
                .collect();
            let dest = pager.get_page_mut(relocated)?;
            write_interior_page(dest, 0, relocated, &cells, rightmost)?;
        }
        other => {
            return Err(BtreeError::UnexpectedPageType {
                page_num: root_page,
                page_type: other,
            })
        }
    }

match descend_index_tree(pager, root_page, usable_size, key, encoding)? {
        IndexDescent::Leaf { leaf_page, .. } => {
            delete_from_leaf(pager, usable_size, leaf_page, key, encoding)
        }
        IndexDescent::InteriorMatch {
            interior_page,
            entry_child,
        } => delete_via_predecessor_swap(pager, usable_size, interior_page, entry_child, encoding),
    }

match extract_max_entry(pager, usable_size, entry_child, encoding, 0)? {
        Some(predecessor_bytes) => {
            let header_start = page1_header_start(interior_page);
            let buf = pager.get_page_mut(interior_page)?.clone();
            let (mut entries, rightmost) = collect_index_interior_entries(
                pager,
                &buf,
                header_start,
                interior_page,
                usable_size,
                encoding,
            )?;
            let entry = entries
                .iter_mut()
                .find(|(child, _, _)| *child == entry_child)
                .ok_or(BtreeError::Internal(
                    "entry_child's routing entry must still exist in interior_page",
                ))?;
            entry.2 = predecessor_bytes;
            let cell_bytes: Vec<Vec<u8>> = entries
                .iter()
                .map(|(child, _, value_bytes)| build_index_interior_cell(*child, value_bytes))
                .collect();
            let buf = pager.get_page_mut(interior_page)?;
            write_index_interior_page(buf, header_start, interior_page, &cell_bytes, rightmost)
        }
        None => {
            // `entry_child`'s entire subtree is drained (nothing left to
            // swap in) — the matched entry is deleted outright, since
            // there is nothing left to preserve.
            pager.deallocate_page(entry_child)?;
            remove_entry_by_child(pager, usable_size, interior_page, entry_child, encoding)
        }
    }

match descend_index_tree(pager, root_page, usable_size, key, encoding)? {
            IndexDescent::Leaf {
                ancestors,
                leaf_page,
            } => (ancestors, leaf_page),
            IndexDescent::InteriorMatch { .. } => return Err(BtreeError::DuplicateKey),
        }

match entries.iter().position(|(child, _, _)| *child == old_page) {
        Some(idx) => {
            entries.insert(idx, (old_page, promoted_key.to_vec(), promoted_bytes));
            let successor = entries
                .get_mut(idx.saturating_add(1))
                .ok_or(BtreeError::Internal(
                    "split successor entry must exist right after insertion",
                ))?;
            successor.0 = new_page;
        }
        None if rightmost == old_page => {
            entries.push((old_page, promoted_key.to_vec(), promoted_bytes));
            rightmost = new_page;
        }
        None => {
            return Err(BtreeError::MissingChildRoute {
                page_num: parent_page,
                child: old_page,
            });
        }
    }

match page_type {
        LEAF_INDEX => {
            let cells = collect_index_leaf_cells(
                pager,
                &content,
                header_start_root,
                root_page,
                usable_size,
                encoding,
            )?;
            let dest = pager.get_page_mut(relocated)?;
            write_index_leaf_page(dest, 0, relocated, &cell_bytes(cells))?;
        }
        INTERIOR_INDEX => {
            let (entries, rightmost) = collect_index_interior_entries(
                pager,
                &content,
                header_start_root,
                root_page,
                usable_size,
                encoding,
            )?;
            let cells: Vec<Vec<u8>> = entries
                .iter()
                .map(|(child, _, value_bytes)| build_index_interior_cell(*child, value_bytes))
                .collect();
            let dest = pager.get_page_mut(relocated)?;
            write_index_interior_page(dest, 0, relocated, &cells, rightmost)?;
        }
        other => {
            return Err(BtreeError::UnexpectedPageType {
                page_num: root_page,
                page_type: other,
            })
        }
    }

match existing {
        None => {
            let next_rowid = max_rowid(pager, header, seq_root)?
                .unwrap_or(0)
                .saturating_add(1);
            let values = [Value::Text(table_name.into()), Value::Integer(rowid)];
            let payload = encode_record(&values, header.text_encoding);
            super::insert_row(pager, header, seq_root, next_rowid, &payload)?;
        }
        Some((row_rowid, current_seq)) if rowid > current_seq => {
            super::delete_row(pager, header, seq_root, row_rowid)?;
            let values = [Value::Text(table_name.into()), Value::Integer(rowid)];
            let payload = encode_record(&values, header.text_encoding);
            super::insert_row(pager, header, seq_root, row_rowid, &payload)?;
        }
        Some(_) => {}
    }

match idx {
        Some(name) => Value::Text(name.into()),
        None => Value::Null,
    }

match self.dirty.entry(page_num) {
            std::collections::hash_map::Entry::Occupied(entry) => Ok(entry.into_mut()),
            std::collections::hash_map::Entry::Vacant(entry) => {
                let page = read_page(&self.wal_pages, &self.source, page_num)?;
                Ok(entry.insert(page))
            }
        }

match wal::WalWriter::open_existing(
                &self.vfs,
                &wal_path,
                self.page_size,
                self.wal_resume.as_ref(),
            ) {
                Ok(writer) => writer,
                // The `-wal` this `Pager` believed was live has vanished —
                // e.g. a concurrent `sqlite3` connection auto-checkpointed
                // and deleted `-wal`/`-shm` on close (#422). `journal_mode`
                // still says `Wal` (this closure only ever runs from that
                // branch), so recover exactly as `switch_journal_to_wal`
                // creates one from scratch, rather than failing the commit.
                Err(wal::WalError::Vfs(VfsError::NotFound { .. })) => self.recreate_wal_locked()?,
                Err(source) => return Err(to_pager_error(source)),
            }

match mode {
            JournalMode::Wal => self.switch_journal_to_wal()?,
            JournalMode::Legacy => self.switch_wal_to_journal()?,
        }

match err {
        JournalError::Vfs(source) => PagerError::Vfs(source),
        other => PagerError::Journal(other),
    }

match victim {
            Some(mut recycled) => match Rc::get_mut(&mut recycled) {
                Some(buf) => {
                    self.source.read_page_into(page_num, buf)?;
                    recycled
                }
                None => self.source.read_page(page_num)?,
            },
            None => self.source.read_page(page_num)?,
        }

match Rc::get_mut(&mut recycled) {
                Some(buf) => {
                    self.source.read_page_into(page_num, buf)?;
                    recycled
                }
                None => self.source.read_page(page_num)?,
            }

match result {
            Err(PagerError::Vfs(crate::storage::row::vfs::VfsError::Locked { .. })) => {}
            Err(other) => panic!("expected Locked, got {other:?}"),
            Ok(_) => panic!("expected Locked, got Ok"),
        }

match result {
            Err(PagerError::Vfs(crate::storage::row::vfs::VfsError::Locked { .. })) => {}
            Err(other) => panic!("expected Locked, got {other:?}"),
            Ok(_) => panic!("expected Locked, got Ok"),
        }

match self {
            VfsError::NotFound { path } => write!(f, "file not found: {path}"),
            VfsError::Locked { path } => write!(f, "database is locked: {path}"),
            VfsError::Io { path, source } => write!(f, "I/O error on {path}: {source}"),
        }

match self {
            VfsError::NotFound { .. } | VfsError::Locked { .. } => None,
            VfsError::Io { source, .. } => Some(source),
        }

match self {
            WalError::HeaderTooShort { len } => {
                write!(f, "WAL header is {len} bytes, need at least {HEADER_LEN}")
            }
            WalError::InvalidMagic { magic } => {
                write!(
                    f,
                    "invalid WAL magic {magic:#010x} (must be 0x377f0682 or 0x377f0683)"
                )
            }
            WalError::InvalidPageSize { page_size } => {
                write!(
                    f,
                    "invalid WAL page size {page_size} (must be a power of two from 512 to 65536)"
                )
            }
            WalError::HeaderChecksumMismatch { stored, computed } => {
                write!(
                    f,
                    "WAL header checksum mismatch: stored {stored:?}, computed {computed:?} — corrupt WAL"
                )
            }
            WalError::Vfs(source) => std::fmt::Display::fmt(source, f),
        }

match magic {
            0x377f_0682 => true,
            0x377f_0683 => false,
            _ => return Err(WalError::InvalidMagic { magic }),
        }

match pre_image {
            Some(content) => {
                pages.insert(page_number, content);
            }
            None => {
                pages.remove(&page_number);
            }
        }

match self {
            PagerError::HotJournal { path } => write!(
                f,
                "hot rollback journal present at {path}: database was not cleanly closed and its main \
                 file may not reflect committed data; refusing to open read-only rather than risk \
                 serving pre-rollback pages as committed"
            ),
            PagerError::Journal(source) => write!(f, "rollback journal is corrupt: {source}"),
            PagerError::Wal { path, source } => write!(f, "reading WAL at {path}: {source}"),
            PagerError::Page(source) => write!(f, "{source}"),
            PagerError::Vfs(source) => write!(f, "{source}"),
            PagerError::Freelist(source) => write!(f, "{source}"),
            PagerError::PendingTransaction => {
                write!(f, "cannot change journal_mode with a pending transaction")
            }
            PagerError::CheckpointIncomplete => write!(
                f,
                "checkpoint did not fully back-fill the WAL while switching journal_mode out of WAL"
            ),
        }

match err {
            PagerError::Wal { source, .. } => {
                assert!(matches!(
                    source,
                    wal::WalError::InvalidPageSize { page_size: 512 }
                ));
            }
            other => panic!("expected PagerError::Wal, got {other:?}"),
        }

match self {
            JournalError::HeaderTooShort(got) => write!(
                f,
                "journal header too short: expected at least {JOURNAL_HEADER_LEN} bytes, got {got}"
            ),
            JournalError::RecordTruncated {
                index,
                expected,
                got,
            } => write!(
                f,
                "journal record {index} truncated: expected {expected} bytes, got {got}"
            ),
            JournalError::Vfs(source) => std::fmt::Display::fmt(source, f),
        }

match self {
            FreelistError::PageTooShort { offset, len } => write!(
                f,
                "freelist trunk page is {len} bytes, too short to read a field at offset {offset}"
            ),
        }

match v {
        Value::Null => 0,
        Value::Integer(_) | Value::Real(_) => 1,
        Value::Text(_) => 2,
        Value::Blob(_) => 3,
    }

match (x.is_nan(), y.is_nan()) {
        (true, true) => Ordering::Equal,
        (true, false) => Ordering::Greater,
        (false, true) => Ordering::Less,
        (false, false) => x.partial_cmp(&y).unwrap_or(Ordering::Equal),
    }

match op {
        BinaryOp::Eq => v == threshold,
        BinaryOp::Ne => v != threshold,
        BinaryOp::Lt => v < threshold,
        BinaryOp::Le => v <= threshold,
        BinaryOp::Gt => v > threshold,
        BinaryOp::Ge => v >= threshold,
        // Every other `BinaryOp` (`AND`/`OR`/arithmetic/`||`/bitwise) is
        // not a comparison and cannot appear here: `EmitMode::Threshold`
        // is only ever constructed by `StandingQuery::new`, which rejects
        // anything but the six comparison operators above.
        _ => false,
    }

match func {
        RangeAggFunc::Count => Value::Int(i64::try_from(values.len()).unwrap_or(i64::MAX)),
        RangeAggFunc::Rate => {
            let secs = size.as_secs_f64();
            if secs <= 0.0 {
                Value::Null
            } else {
                Value::Float(values.len() as f64 / secs)
            }
        }
        RangeAggFunc::Sum => Value::Float(values.iter().filter_map(Value::as_f64).sum()),
        RangeAggFunc::Avg => {
            let nums: Vec<f64> = values.iter().filter_map(Value::as_f64).collect();
            if nums.is_empty() {
                Value::Null
            } else {
                Value::Float(nums.iter().sum::<f64>() / nums.len() as f64)
            }
        }
        RangeAggFunc::Min => values
            .iter()
            .filter_map(Value::as_f64)
            .fold(None, |acc: Option<f64>, v| {
                Some(acc.map_or(v, |a| a.min(v)))
            })
            .map_or(Value::Null, Value::Float),
        RangeAggFunc::Max => values
            .iter()
            .filter_map(Value::as_f64)
            .fold(None, |acc: Option<f64>, v| {
                Some(acc.map_or(v, |a| a.max(v)))
            })
            .map_or(Value::Null, Value::Float),
    }

match self {
            Value::Int(v) => Some(*v as f64),
            Value::Float(v) => Some(*v),
            _ => None,
        }

match v {
        crate::value::Value::Null | crate::value::Value::Blob(_) => Value::Null,
        crate::value::Value::Integer(i) => Value::Int(i),
        crate::value::Value::Real(f) => Value::Float(f),
        crate::value::Value::Text(s) => Value::Str(s.to_string().into()),
    }

match opcodes.as_slice() {
                [combine @ Opcode::Combine { .. }] => Some((Some(*combine), None, None)),
                [combine @ Opcode::Combine { .. }, sort @ Opcode::Sort { .. }] => {
                    Some((Some(*combine), Some(*sort), None))
                }
                [combine @ Opcode::Combine { .. }, limit @ Opcode::Limit { .. }] => {
                    Some((Some(*combine), None, Some(*limit)))
                }
                [combine @ Opcode::Combine { .. }, sort @ Opcode::Sort { .. }, limit @ Opcode::Limit { .. }] => {
                    Some((Some(*combine), Some(*sort), Some(*limit)))
                }
                _ => None,
            }

match (matches!(a, Value::Null), matches!(b, Value::Null)) {
        (true, true) => Ordering::Equal,
        (true, false) => Ordering::Greater,
        (false, true) => Ordering::Less,
        (false, false) => {
            let ord = match (a.as_f64(), b.as_f64()) {
                (Some(x), Some(y)) => x.partial_cmp(&y).unwrap_or(Ordering::Equal),
                // #266: compare `Str`/`Str` directly -- `Value`'s `Display`
                // prints a `Str`'s contents verbatim (no quoting), so this
                // is byte-identical to the `to_string()` fallback below
                // without the two allocations.
                _ => match (a, b) {
                    (Value::Str(x), Value::Str(y)) => x.cmp(y),
                    _ => a.to_string().cmp(&b.to_string()),
                },
            };
            // ORDER BY direction flips the comparison, not the sort itself.
            if descending {
                ord.reverse()
            } else {
                ord
            }
        }
    }

match (a.as_f64(), b.as_f64()) {
                (Some(x), Some(y)) => x.partial_cmp(&y).unwrap_or(Ordering::Equal),
                // #266: compare `Str`/`Str` directly -- `Value`'s `Display`
                // prints a `Str`'s contents verbatim (no quoting), so this
                // is byte-identical to the `to_string()` fallback below
                // without the two allocations.
                _ => match (a, b) {
                    (Value::Str(x), Value::Str(y)) => x.cmp(y),
                    _ => a.to_string().cmp(&b.to_string()),
                },
            }

match self {
            VmError::UnknownColumn { opcode, column } => {
                write!(f, "{opcode}: unknown column: {column}")
            }
            VmError::UnknownRegister { opcode, register } => {
                write!(f, "{opcode}: unknown register: {register}")
            }
            VmError::RegisterLengthMismatch { opcode } => {
                write!(f, "{opcode}: register length mismatch")
            }
            VmError::UnknownJoinTable { opcode, table } => {
                write!(f, "{opcode}: unknown join table: {table}")
            }
            VmError::StepLimitExceeded { opcode, limit } => {
                write!(f, "{opcode}: exceeded step limit of {limit}")
            }
            VmError::UnsupportedOp { opcode, op } => {
                write!(f, "{opcode}: no dispatch for {op}")
            }
            VmError::MissingWindowArgument { opcode, func } => {
                write!(f, "{opcode}: {func:?} requires an argument register")
            }
            VmError::MalformedProgram { opcode, reason } => {
                write!(f, "{opcode}: malformed program: {reason}")
            }
            VmError::SegmentLoad { reason } => write!(f, "segment load failed: {reason}"),
        }

match value {
                Value::Int(v) => {
                    0u8.hash(state);
                    v.hash(state);
                }
                Value::Float(v) => {
                    1u8.hash(state);
                    v.to_bits().hash(state);
                }
                Value::Bool(v) => {
                    2u8.hash(state);
                    v.hash(state);
                }
                Value::Str(v) => {
                    3u8.hash(state);
                    v.hash(state);
                }
                Value::Null => 4u8.hash(state),
            }

match value {
                Value::Int(v) => {
                    0u8.hash(state);
                    v.hash(state);
                }
                Value::Float(v) => {
                    1u8.hash(state);
                    v.to_bits().hash(state);
                }
                Value::Bool(v) => {
                    2u8.hash(state);
                    v.hash(state);
                }
                Value::Str(v) => {
                    3u8.hash(state);
                    v.hash(state);
                }
                Value::Null => 4u8.hash(state),
            }

match source.next_batch() {
            Some(b) => b,
            None => return Ok(Vec::new()),
        }

match op {
                Opcode::NextSegment { loop_start } => match source.next_batch() {
                    Some(next) => {
                        batch = next;
                        // #265: a new segment's registers start over
                        // (`LoadColumn` re-loads full columns at the top
                        // of the loop body), so any selection pending
                        // from the previous segment is meaningless here.
                        self.selection = None;
                        pc = *loop_start;
                    }
                    None => pc = pc.saturating_add(1),
                },
                Opcode::Halt => break,
                other => {
                    self.step(&batch, other)?;
                    pc = pc.saturating_add(1);
                }
            }

match source.next_batch() {
                    Some(next) => {
                        batch = next;
                        // #265: a new segment's registers start over
                        // (`LoadColumn` re-loads full columns at the top
                        // of the loop body), so any selection pending
                        // from the previous segment is meaningless here.
                        self.selection = None;
                        pc = *loop_start;
                    }
                    None => pc = pc.saturating_add(1),
                }

match op {
            Opcode::LoadColumn { reg, column } => {
                let values =
                    batch
                        .columns
                        .get(column.as_ref())
                        .ok_or_else(|| VmError::UnknownColumn {
                            opcode,
                            column: column.to_string(),
                        })?;
                self.registers.insert(*reg, Arc::clone(values));
            }
            Opcode::LoadConst { reg, value } => {
                self.registers
                    .insert(*reg, Arc::new(vec![value.clone(); batch.num_rows]));
            }
            Opcode::Map { dst, op, a, b } => {
                // #265: reads registers elementwise (no row-index
                // concept), so any pending selection must be resolved
                // (compacted) first rather than taught to this opcode.
                self.resolve_selection(opcode)?;
                let (a_vals, b_vals) = (self.reg(*a, opcode)?, self.reg(*b, opcode)?);
                if a_vals.len() != b_vals.len() {
                    return Err(VmError::RegisterLengthMismatch { opcode });
                }
                let result: Vec<Value> = a_vals
                    .iter()
                    .zip(b_vals)
                    .map(|(x, y)| apply_map_op(*op, x, y))
                    .collect();
                self.registers.insert(*dst, Arc::new(result));
            }
            Opcode::Call { dst, name, args } => {
                // Elementwise, like `Map`: resolve any pending selection
                // first (see the comment on that arm).
                self.resolve_selection(opcode)?;
                let arg_regs: Vec<&[Value]> = args
                    .iter()
                    .map(|&a| self.reg(a, opcode))
                    .collect::<Result<_>>()?;
                let num_rows = arg_regs.first().map_or(batch.num_rows, |r| r.len());
                if arg_regs.iter().any(|r| r.len() != num_rows) {
                    return Err(VmError::RegisterLengthMismatch { opcode });
                }
                let mut call_args = vec![crate::value::Value::Null; arg_regs.len()];
                let mut result = Vec::with_capacity(num_rows);
                for row in 0..num_rows {
                    for (slot, reg) in call_args.iter_mut().zip(&arg_regs) {
                        *slot = to_scalar_value(&reg[row]);
                    }
                    let value = crate::functions::call(name, &call_args)
                        .map_or(Value::Null, from_scalar_value);
                    result.push(value);
                }
                self.registers.insert(*dst, Arc::new(result));
            }
            Opcode::Filter { predicate } => {
                // #265: produces a selection vector (surviving row
                // indices) instead of eagerly compacting every live
                // register -- registers stay exactly as they are;
                // whichever opcode later actually needs dense rows
                // resolves this (see `Selection`).
                let mask: Vec<bool> = self
                    .reg(*predicate, opcode)?
                    .iter()
                    .map(|v| matches!(v, Value::Bool(true)))
                    .collect();
                let base_len = mask.len();
                for values in self.registers.values() {
                    if values.len() != base_len {
                        return Err(VmError::RegisterLengthMismatch { opcode });
                    }
                }
                let source_indices: Vec<u32> = match self.selection.take() {
                    Some(existing) => {
                        if existing.base_len != base_len {
                            return Err(VmError::RegisterLengthMismatch { opcode });
                        }
                        existing.indices
                    }
                    // #110: size the surviving-index buffer to the actual
                    // survivor count up front (not the pre-filter length)
                    // -- at 50% selectivity on a 10M-row scan, over-
                    // allocating by 2x is real peak-RSS waste for no
                    // benefit (the excess capacity is never used).
                    None => (0..u32::try_from(base_len).unwrap_or(u32::MAX)).collect(),
                };
                let kept_len = mask.iter().filter(|&&keep| keep).count();
                let mut indices = Vec::with_capacity(kept_len);
                for idx in source_indices {
                    if mask.get(idx as usize).copied().unwrap_or(false) {
                        indices.push(idx);
                    }
                }
                self.selection = Some(Selection { base_len, indices });
            }
            Opcode::Reduce { func, src, dst } => {
                // #265: see the comment on `Map`'s same call.
                self.resolve_selection(opcode)?;
                let result = match src {
                    Some(reg) => reduce_values(*func, self.reg(*reg, opcode)?),
                    None => reduce_count_star(*func, batch.num_rows),
                };
                self.registers.insert(*dst, Arc::new(vec![result]));
            }
            Opcode::GroupReduce {
                group_by,
                aggs,
                agg_dst,
            } => {
                // #265: lazily resolves any pending selection -- only the
                // group-key and per-aggregate source registers this
                // opcode actually reads are indexed through it, instead
                // of every live register being eagerly compacted back in
                // `Filter`. Taken up front so the borrows below are of
                // `self.registers` alone, not all of `self`.
                let selection = self.selection.take();
                let key_columns: Vec<&[Value]> = group_by
                    .iter()
                    .map(|reg| self.reg(*reg, opcode))
                    .collect::<Result<_>>()?;
                let base_len = match &selection {
                    Some(sel) => sel.base_len,
                    None => match key_columns.first() {
                        Some(c) => c.len(),
                        None => match aggs.iter().find_map(|(_, src)| {
                            src.map(|reg| self.reg(reg, opcode).map(<[Value]>::len))
                        }) {
                            Some(len) => len?,
                            // `COUNT(*)` alone: no key or source column
                            // carries the row count, but every live
                            // register has the post-`Filter` length
                            // (RegisterLengthMismatch guards that), so any
                            // one of them is it; with no register at all
                            // nothing was filtered and the batch's own row
                            // count is exact.
                            None => self
                                .registers
                                .values()
                                .next()
                                .map_or(batch.num_rows, |v| v.len()),
                        },
                    },
                };
                for c in &key_columns {
                    if c.len() != base_len {
                        return Err(VmError::RegisterLengthMismatch { opcode });
                    }
                }
                let num_rows = selection.as_ref().map_or(base_len, |sel| sel.indices.len());
                let physical = |row: usize| {
                    selection
                        .as_ref()
                        .map_or(row, |sel| sel.indices[row] as usize)
                };

                let mut group_index: HashMap<GroupKey, usize> = HashMap::new();
                let mut group_keys: Vec<Vec<Value>> = Vec::new();
                let mut row_group: Vec<usize> = Vec::with_capacity(num_rows);
                for row in 0..num_rows {
                    let p = physical(row);
                    let key: Vec<Value> = key_columns.iter().map(|c| c[p].clone()).collect();
                    let group = *group_index.entry(GroupKey(key.clone())).or_insert_with(|| {
                        group_keys.push(key);
                        group_keys.len() - 1
                    });
                    row_group.push(group);
                }
                let num_groups = group_keys.len();

                for (i, reg) in group_by.iter().enumerate() {
                    let column: Vec<Value> = group_keys.iter().map(|k| k[i].clone()).collect();
                    self.registers.insert(*reg, Arc::new(column));
                }

                for ((func, src), dst) in aggs.iter().zip(agg_dst.iter()) {
                    let mut per_group: Vec<Vec<Value>> = vec![Vec::new(); num_groups];
                    match src {
                        Some(reg) => {
                            // #110: borrow instead of `.to_vec()` -- same
                            // redundant-clone pattern as the old `Emit`.
                            let values = self.reg(*reg, opcode)?;
                            if values.len() != base_len {
                                return Err(VmError::RegisterLengthMismatch { opcode });
                            }
                            for (row, group) in row_group.iter().enumerate() {
                                per_group[*group].push(values[physical(row)].clone());
                            }
                        }
                        None => {
                            for group in &row_group {
                                per_group[*group].push(Value::Null);
                            }
                        }
                    }
                    let result: Vec<Value> = per_group
                        .iter()
                        .map(|vals| {
                            if src.is_none() {
                                Value::Int(len_to_i64(vals.len()))
                            } else {
                                reduce_values(*func, vals)
                            }
                        })
                        .collect();
