match checked_add(&max, &Value::Integer(1)) {
            Value::Real(r) => assert!((r - 9_223_372_036_854_775_808.0).abs() < 1.0),
            other => panic!("expected REAL promotion, got {other:?}"),
        }

match checked_mul(&max, &Value::Integer(2)) {
            Value::Real(r) => assert!(r > i64::MAX as f64),
            other => panic!("expected REAL promotion, got {other:?}"),
        }

match self {
            Cell::Null => Ok(()),
            Cell::Int(n) => write!(f, "{n}"),
            Cell::Real(x) => f.write_str(&crate::value::format_real(*x)),
            Cell::Bool(b) => f.write_str(if *b { "1" } else { "0" }),
            Cell::Text(s) => f.write_str(s),
            Cell::Blob(bytes) => {
                f.write_str("X'")?;
                for b in bytes {
                    write!(f, "{b:02X}")?;
                }
                f.write_str("'")
            }
        }

match (stmts.next(), stmts.next()) {
        (Some(one), None) => Ok(one),
        (None, _) => Err(EngineError::new(ErrorKind::Parse, "empty statement")),
        (Some(_), Some(_)) => Err(EngineError::new(
            ErrorKind::Unsupported,
            "EXPLAIN takes a single statement",
        )),
    }
